// ================================================================
//  REPORT  : Sales Report For Commission Detailed
//  PURPOSE : Van salesman daily sales tracking — Badriya Sweets
//  VERSION : ERPNext v15
//
//  COLUMN SETUP  →  Report › Columns tab (exact order):
//
//  #   Fieldname             Label                      Type      Options
//  1   posting_date          Date                       Date
//  2   customer              Customer Code              Link      Customer
//  3   customer_name         Customer Name              Data
//  4   sales_invoice         Sales Invoice              Link      Sales Invoice
//  5   sales_return          Sales Return               Data      (NOT Link)
//  6   return_dates          Return Date(s)             Data
//  7   return_grand_total    Return Amt (Incl. VAT)     Currency
//  8   return_net_amount     Return Amt (Excl. VAT)     Currency
//  9   invoice_grand_total   Invoice Amt (Incl. VAT)    Currency
//  10  invoice_net_amount    Invoice Amt (Excl. VAT)    Currency
//  11  apply_discount_on     Discount On                Data
//  12  discount_amount       Discount Amt               Currency
//  13  payment_entry         Payment Entry              Data      (NOT Link)
//  14  collected_grand_total Collected (Incl. VAT)      Currency
//  15  collected_net_amount  Collected (Excl. VAT)      Currency
//  16  outstanding_amount    Outstanding                Currency
//
//  REPORT SETTINGS:
//  ✅ Add Total Row     ✅ Is Standard = Yes
//
//  RETURNS CAPTURED:
//  1. Direct link — return_against = invoice (standard ERPNext)
//  2. JE Reconciliation — matched via Payment Ledger Entry
//     (returns reconciled through Payment Reconciliation tool)
//  Both sources merged and deduplicated in SQL.
//
//  STANDALONE RETURNS (no return_against, not JE-matched):
//  Fetched separately via frappe.db.get_list after report loads
//  and injected as purple rows. Warehouse matched via item table.
// ================================================================

frappe.query_reports["Sales Report For Commission Detailed"] = {

    // ── FILTERS ──────────────────────────────────────────────────
    filters: [
        {
            fieldname: "from_date",
            label: __("From Date"),
            fieldtype: "Date",
            default: frappe.datetime.month_start(),
            reqd: 1
        },
        {
            fieldname: "to_date",
            label: __("To Date"),
            fieldtype: "Date",
            default: frappe.datetime.month_end(),
            reqd: 1
        },
        {
            fieldname: "warehouse",
            label: __("Van / Warehouse"),
            fieldtype: "Link",
            options: "Warehouse",
            reqd: 1,
            get_query: () => ({ filters: { is_group: 0 } })
        },
        {
            fieldname: "customer",
            label: __("Customer"),
            fieldtype: "Link",
            options: "Customer"
        }
    ],

    // ── ROW FORMATTER ────────────────────────────────────────────
    formatter(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);
        if (!data) return value;

        const isStandalone = data.is_standalone_return === 1 || data.is_standalone_return === "1";
        const isPartial    = data.is_partial_return    === 1 || data.is_partial_return    === "1";

        // ── Date ──
        if (column.fieldname === "posting_date")
            return `<span style="color:#5c6bc0;font-weight:500">${value}</span>`;

        // ── Customer name ──
        if (column.fieldname === "customer_name")
            return `<span style="color:#212121;font-weight:600">${value}</span>`;

        if (column.fieldname === "sales_invoice") {
            if (isStandalone) {
                return isPartial
                    ? `<span style="color:#6a1b9a;font-size:11px;font-weight:600;
                        background:#f3e5f5;padding:2px 8px;border-radius:10px;
                        border:1px solid #ce93d8">⚡ Partial Unallocated</span>`
                    : `<span style="color:#6a1b9a;font-size:11px;font-weight:600;
                        background:#f3e5f5;padding:2px 8px;border-radius:10px;
                        border:1px solid #ce93d8">⚡ Standalone Return</span>`;
            }
            if (!data.sales_invoice)
                return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#1a73e8;font-weight:600">${value}</span>`;
        }

        // ── Sales Return → pill links ──
        if (column.fieldname === "sales_return") {
            if (!data.sales_return || !data.sales_return.trim())
                return `<span style="color:#ccc">—</span>`;
            const bg    = isStandalone ? "#f3e5f5" : "#fdecea";
            const color = isStandalone ? "#6a1b9a" : "#c62828";
            const bdr   = isStandalone ? "#ce93d8" : "#ef9a9a";
            const pills = data.sales_return
                .split(",").map(s => s.trim()).filter(Boolean)
                .map(n => `<a href="/app/sales-invoice/${encodeURIComponent(n)}"
                    target="_blank" onclick="event.stopPropagation()"
                    style="display:inline-block;margin:1px 3px 1px 0;padding:2px 9px;
                    background:${bg};color:${color};border:1px solid ${bdr};
                    border-radius:12px;font-size:11px;font-weight:600;
                    text-decoration:none;white-space:nowrap;line-height:1.6">${n}</a>`)
                .join("");
            return `<div style="display:flex;flex-wrap:wrap;gap:2px;padding:2px 0">${pills}</div>`;
        }

        // ── Return dates ──
        if (column.fieldname === "return_dates") {
            if (!data.return_dates || !data.return_dates.trim())
                return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#c62828;font-size:11px;font-weight:500">${data.return_dates}</span>`;
        }

        // ── Return amounts ──
        if (column.fieldname === "return_grand_total" || column.fieldname === "return_net_amount") {
            const amt = column.fieldname === "return_grand_total"
                ? flt(data.return_grand_total, 2)
                : flt(data.return_net_amount,  2);
            if (amt === 0 && !data.sales_return)
                return `<span style="color:#ccc">—</span>`;
            if (amt === 0)
                return `<span style="color:#ccc">0.00</span>`;
            return `<span style="color:#c62828;font-weight:600;font-style:italic">${value}</span>`;
        }

        // ── Invoice VAT incl ──
        if (column.fieldname === "invoice_grand_total") {
            if (isStandalone) return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#1565c0;font-weight:600">${value}</span>`;
        }

        // ── Invoice VAT excl ──
        if (column.fieldname === "invoice_net_amount") {
            if (isStandalone) return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#0d47a1;font-weight:700">${value}</span>`;
        }

        // ── Discount on ──
        if (column.fieldname === "apply_discount_on") {
            if (!data.apply_discount_on || flt(data.discount_amount) === 0)
                return `<span style="color:#ccc">—</span>`;
            const isGrand = data.apply_discount_on === "Grand Total";
            return `<span style="display:inline-block;padding:2px 7px;
                background:${isGrand ? "#fff8e1" : "#fce4ec"};
                color:${isGrand ? "#f57f17" : "#880e4f"};
                border-radius:10px;font-size:10px;font-weight:600">
                ${data.apply_discount_on}</span>`;
        }

        // ── Discount amount ──
        if (column.fieldname === "discount_amount") {
            if (flt(data.discount_amount) === 0)
                return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#e65100;font-weight:600">− ${value}</span>`;
        }

        // ── Payment Entry → individual blue pill links ──
        if (column.fieldname === "payment_entry") {
            if (!data.payment_entry || !data.payment_entry.trim())
                return `<span style="color:#ccc">—</span>`;
            const pills = data.payment_entry
                .split(",").map(s => s.trim()).filter(Boolean)
                .map(n => `<a href="/app/payment-entry/${encodeURIComponent(n)}"
                    target="_blank" onclick="event.stopPropagation()"
                    style="display:inline-block;margin:1px 3px 1px 0;padding:2px 9px;
                    background:#e3f2fd;color:#1565c0;border:1px solid #90caf9;
                    border-radius:12px;font-size:11px;font-weight:600;
                    text-decoration:none;white-space:nowrap;line-height:1.6">${n}</a>`)
                .join("");
            return `<div style="display:flex;flex-wrap:wrap;gap:2px;padding:2px 0">${pills}</div>`;
        }

        // ── Collected VAT incl ──
        if (column.fieldname === "collected_grand_total") {
            if (isStandalone || flt(data.collected_grand_total) === 0)
                return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#388e3c;font-weight:600">${value}</span>`;
        }

        // ── Collected VAT excl (commission base) ──
        if (column.fieldname === "collected_net_amount") {
            if (isStandalone || flt(data.collected_net_amount) === 0)
                return `<span style="color:#ccc">—</span>`;
            return `<span style="color:#1b5e20;font-weight:700">${value}</span>`;
        }

        // ── Outstanding ──
        if (column.fieldname === "outstanding_amount") {
            // Standalone with outstanding — show in red (it's a credit owed)
            if (isStandalone && flt(data.outstanding_amount) !== 0)
                return `<span style="color:#6a1b9a;font-weight:700">${value}</span>`;
            // Standalone with no outstanding — dash
            if (isStandalone)
                return `<span style="color:#ccc">—</span>`;
            // Normal invoice — cleared or pending
            if (flt(data.outstanding_amount) <= 0)
                return `<span style="color:#2e7d32;font-weight:700">✓ Cleared</span>`;
            return `<span style="color:#e65100;font-weight:700">${value}</span>`;
        }

        return value;
    },

    // ── TOOLBAR ──────────────────────────────────────────────────
    onload(report) {
        report.page.add_inner_button(__("⬇ Export Excel"), () => {
            report.export_report("Excel");
        });
    }
};
